async function updateLearning(){try{const r=await fetch('/api/learning-status');if(!r.ok)throw Error();const s=await r.json(),gb=n=>(n/1e9).toFixed(1);document.querySelector('#status').textContent=(s.state==='downloading'?'Downloading to SSD: ':'Stored on SSD: ')+gb(s.stored_bytes)+' GB / approximately '+gb(s.total_bytes)+' GB'+(s.state==='downloading'&&s.stored_bytes===0?' · Preparing the course files…':'');document.querySelector('#progress').value=Math.min(100,s.stored_bytes/s.total_bytes*100);}catch(e){document.querySelector('#status').textContent='Download status is temporarily unavailable.';}}updateLearning();setInterval(updateLearning,30000);